-- V1: model registry (roadmap task 2.3 builds the API on this table).
--
-- Later tables (datasets, profiles, runs, results) are added by the
-- migrations of the features that use them, so the schema never contains
-- tables that no code reads or writes.
--
-- Applied migrations are immutable: change the schema with a new V<n> file.

CREATE TABLE monitored_model (
    -- Generated by the application (not a database sequence), so ids are
    -- not guessable and can be assigned before the row is inserted.
    id                UUID         PRIMARY KEY,
    name              VARCHAR(100) NOT NULL,
    task_type         VARCHAR(32)  NOT NULL,
    -- Optional: drift monitoring works without them; performance
    -- monitoring (Milestone 3) needs both.
    target_column     VARCHAR(255),
    prediction_column VARCHAR(255),
    created_at        TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT uq_monitored_model_name UNIQUE (name),
    CONSTRAINT ck_monitored_model_name_not_blank CHECK (btrim(name) <> ''),
    CONSTRAINT ck_monitored_model_task_type CHECK (
        task_type IN ('BINARY_CLASSIFICATION', 'MULTICLASS_CLASSIFICATION', 'REGRESSION')
    )
);

COMMENT ON TABLE monitored_model IS 'A model whose inputs and predictions DriftWatch monitors';
COMMENT ON COLUMN monitored_model.task_type IS 'Determines which performance metrics apply';
